import tkinter as tk
import numpy as np


class Calculator(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Calculator")
        self.expression = ""

        self.display = tk.Entry(self, font=("Arial", 20), justify="right")
        self.display.grid(row=0, column=0, columnspan=4, sticky="nsew")

        buttons = [
            "7", "8", "9", "/",
            "4", "5", "6", "*",
            "1", "2", "3", "-",
            "0", ".", "=", "+",
            "C",
        ]
        for i, label in enumerate(buttons):
            row, col = divmod(i, 4)
            tk.Button(
                self,
                text=label,
                font=("Arial", 16),
                command=lambda l=label: self.on_click(l),
            ).grid(row=row + 1, column=col, sticky="nsew")

        for col in range(4):
            self.grid_columnconfigure(col, weight=1)
        for row in range(6):
            self.grid_rowconfigure(row, weight=1)

    def on_click(self, label):
        if label == "C":
            self.expression = ""
        elif label == "=":
            try:
                result = np.float64(eval(self.expression, {"__builtins__": {}}, {}))
                self.expression = str(result)
            except Exception:
                self.expression = "Error"
        else:
            if self.expression in ("Error",):
                self.expression = ""
            self.expression += label

        self.display.delete(0, tk.END)
        self.display.insert(0, self.expression)


if __name__ == "__main__":
    Calculator().mainloop()

