# Removed: natural_snow, rain, fog_cloud
# Kept:    snowmaking, no_snowmaking, obscured, lens_covered

LABELS = [
    "snowmaking",
    "no_snowmaking",
    "obscured",
    "lens_covered",
]
NUM_CLASSES = len(LABELS)
LABEL_TO_INDEX = {label: i for i, label in enumerate(LABELS)}
INDEX_TO_LABEL = {i: label for label, i in LABEL_TO_INDEX.items()}


def load_labels(records):
    """Drop rows whose label is no longer part of the 4-class schema."""
    kept, dropped = [], []
    for record in records:
        if record["label"] in LABEL_TO_INDEX:
            kept.append(record)
        else:
            dropped.append(record)
    if dropped:
        print(f"dropped {len(dropped)} rows with retired labels")
    return kept


def build_model(input_shape):
    import tensorflow as tf

    return tf.keras.Sequential(
        [
            tf.keras.layers.Input(shape=input_shape),
            tf.keras.layers.Conv2D(32, 3, activation="relu"),
            tf.keras.layers.MaxPooling2D(),
            tf.keras.layers.Conv2D(64, 3, activation="relu"),
            tf.keras.layers.MaxPooling2D(),
            tf.keras.layers.Flatten(),
            tf.keras.layers.Dense(128, activation="relu"),
            tf.keras.layers.Dense(NUM_CLASSES, activation="softmax"),
        ]
    )

# Audit of direct roi.x1/y1/x2/y2 access in cv_label_images.py.
# ROI.coords normalizes to (min_x, min_y, max_x, max_y); a saved config with
# y1 > y2 crashes Pillow's ImageDraw.rectangle.


class ROI:
    def __init__(self, x1, y1, x2, y2, name=""):
        self.x1, self.y1, self.x2, self.y2 = x1, y1, x2, y2
        self.name = name

    @property
    def coords(self):
        return (
            min(self.x1, self.x2),
            min(self.y1, self.y2),
            max(self.x1, self.x2),
            max(self.y1, self.y2),
        )


def draw_roi(canvas, roi):
    # FIXED: tkinter tolerates inverted rectangles, but the label was being
    # placed at the raw (x1, y1), which lands at the bottom for inverted ROIs.
    left, top, right, bottom = roi.coords
    canvas.create_rectangle(left, top, right, bottom, outline="red", width=2)
    canvas.create_text(left + 4, top + 4, text=roi.name, anchor="nw", fill="red")


def crop_roi(image, roi):
    # FIXED: Image.crop raises on an inverted box.
    return image.crop(roi.coords)


def update_roi_list(listbox, rois):
    # FIXED: display the normalized box so the list matches what is drawn.
    listbox.delete(0, "end")
    for roi in rois:
        left, top, right, bottom = roi.coords
        listbox.insert("end", f"{roi.name}: ({left}, {top}) -> ({right}, {bottom})")


def save_labels(writer, rois):
    # UNCHANGED (intentional): the CSV/JSON export must reflect the actual
    # stored values, so raw attributes stay raw here.
    for roi in rois:
        writer.writerow([roi.name, roi.x1, roi.y1, roi.x2, roi.y2])

import json
from pathlib import Path

LABELS_PATH = Path("labels.json")


def load_labels():
    if LABELS_PATH.exists():
        return json.loads(LABELS_PATH.read_text())
    return {}


def resume_index(image_paths, labels):
    """Return the index of the first unlabeled image, resuming where we left off."""
    for i, path in enumerate(image_paths):
        if path.name not in labels:
            return i
    return len(image_paths) - 1


def start(image_paths):
    labels = load_labels()
    index = resume_index(image_paths, labels)
    print(f"resuming at image {index + 1}/{len(image_paths)}: {image_paths[index].name}")
    return index

