import os
from pathlib import Path

DATA_CACHE_DIR = Path(os.environ.get("DATA_CACHE_DIR", "~/.cache/app")).expanduser()


def ensure_cache_dir():
    DATA_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    return DATA_CACHE_DIR


def cache_path(name):
    return ensure_cache_dir() / name


def clear_cache():
    for path in DATA_CACHE_DIR.glob("*"):
        if path.is_file():
            path.unlink()

import tkinter as tk

THEMES = {
    "light": {"bg": "#ffffff", "fg": "#111111", "entry_bg": "#f2f2f2"},
    "dark": {"bg": "#1e1e1e", "fg": "#e8e8e8", "entry_bg": "#2b2b2b"},
}


class ThemedApp(tk.Tk):
    def __init__(self):
        super().__init__()
        self.theme = "light"

        self.toggle_button = tk.Button(
            self, text="Dark mode", command=self.toggle_theme
        )
        self.toggle_button.pack(anchor="ne", padx=8, pady=8)
        self.entry = tk.Entry(self)
        self.entry.pack(fill="x", padx=8, pady=8)

        self.apply_theme()

    def toggle_theme(self):
        self.theme = "dark" if self.theme == "light" else "light"
        self.apply_theme()

    def apply_theme(self):
        colors = THEMES[self.theme]
        self.configure(bg=colors["bg"])
        self.toggle_button.configure(
            bg=colors["bg"],
            fg=colors["fg"],
            activebackground=colors["entry_bg"],
            text="Light mode" if self.theme == "dark" else "Dark mode",
        )
        self.entry.configure(
            bg=colors["entry_bg"], fg=colors["fg"], insertbackground=colors["fg"]
        )


if __name__ == "__main__":
    ThemedApp().mainloop()

