import tkinter as tk


class TemperatureConverter(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Temperature Converter")

        self.value = tk.StringVar(value="0")
        self.result = tk.StringVar(value="")

        tk.Entry(self, textvariable=self.value).pack(fill="x", padx=8, pady=8)
        buttons = tk.Frame(self)
        buttons.pack(fill="x")
        tk.Button(buttons, text="C -> F", command=self.to_fahrenheit).pack(
            side="left", expand=True, fill="x"
        )
        tk.Button(buttons, text="F -> C", command=self.to_celsius).pack(
            side="left", expand=True, fill="x"
        )
        tk.Label(self, textvariable=self.result, font=("Arial", 16)).pack(pady=8)

    def read_value(self):
        try:
            return float(self.value.get())
        except ValueError:
            self.result.set("Enter a number")
            return None

    def to_fahrenheit(self):
        celsius = self.read_value()
        if celsius is not None:
            self.result.set(f"{celsius * 9 / 5 + 32:.2f} F")

    def to_celsius(self):
        fahrenheit = self.read_value()
        if fahrenheit is not None:
            self.result.set(f"{(fahrenheit - 32) * 5 / 9:.2f} C")


if __name__ == "__main__":
    TemperatureConverter().mainloop()

