"""paginate.py -- fixed off-by-one that dropped the last item of the last page.

The slice end was computed as `start + per_page - 1`, which is an inclusive
bound applied to Python's exclusive slice, so every page lost its final item.
"""

import math


def paginate(items, page, per_page):
    if page < 1 or per_page < 1:
        raise ValueError("page and per_page must be >= 1")

    start = (page - 1) * per_page
    end = start + per_page  # was: start + per_page - 1
    return items[start:end]


def page_count(items, per_page):
    return math.ceil(len(items) / per_page)

import argparse
from pathlib import Path


def parse_args():
    parser = argparse.ArgumentParser(description="Process an input file.")
    parser.add_argument("input_path", type=Path, help="path to the input file")
    parser.add_argument(
        "-o", "--output", type=Path, default=None, help="path to write results to"
    )
    return parser.parse_args()


def main():
